    ["semantic.combat.human_kill.shaken.line_01"] = {
        ["canonicalConcept"] = "SEMANTIC_COMBAT_HUMAN_KILL_SHAKEN_LINE_01",
        ["contentOwner"] = "projecthoomans.dialogue_content.combat_human",
        ["id"] = "phrase.semantic.combat.human_kill.shaken.line_01",
        ["semanticTemplateID"] = "semantic.combat.human_kill.shaken.line_01",
        ["styles"] = {
            ["neutral"] = {
                {
                    ["fallback"] = "Jesus... he's dead.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_01.neutral.01",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_01.neutral.01",
                    ["phraseID"] = "neutral.01",
                },
                {
                    ["fallback"] = "I... I really killed him.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_01.neutral.02",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_01.neutral.02",
                    ["phraseID"] = "neutral.02",
                },
                {
                    ["fallback"] = "God... look at him lying there.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_01.neutral.03",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_01.neutral.03",
                    ["phraseID"] = "neutral.03",
                },
                {
                    ["fallback"] = "He stopped moving... he's really gone.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_01.neutral.04",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_01.neutral.04",
                    ["phraseID"] = "neutral.04",
                },
                {
                    ["fallback"] = "I had to do it... he was shooting at us.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_01.neutral.05",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_01.neutral.05",
                    ["phraseID"] = "neutral.05",
                },
                {
                    ["fallback"] = "Lord help us... what have we done?",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_01.neutral.06",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_01.neutral.06",
                    ["phraseID"] = "neutral.06",
                },
                {
                    ["fallback"] = "He's dead. I can't look at it.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_01.neutral.07",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_01.neutral.07",
                    ["phraseID"] = "neutral.07",
                },
                {
                    ["fallback"] = "His eyes are still open... Jesus.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_01.neutral.08",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_01.neutral.08",
                    ["phraseID"] = "neutral.08",
                },
                {
                    ["fallback"] = "I didn't want this... but he wouldn't stop.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_01.neutral.09",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_01.neutral.09",
                    ["phraseID"] = "neutral.09",
                },
                {
                    ["fallback"] = "God forgive me. He's dead.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_01.neutral.10",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_01.neutral.10",
                    ["phraseID"] = "neutral.10",
                },
            },
        },
    },
    ["semantic.combat.human_kill.shaken.line_02"] = {
        ["canonicalConcept"] = "SEMANTIC_COMBAT_HUMAN_KILL_SHAKEN_LINE_02",
        ["contentOwner"] = "projecthoomans.dialogue_content.combat_human",
        ["id"] = "phrase.semantic.combat.human_kill.shaken.line_02",
        ["semanticTemplateID"] = "semantic.combat.human_kill.shaken.line_02",
        ["styles"] = {
            ["neutral"] = {
                {
                    ["fallback"] = "God. That was a person.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_02.neutral.01",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_02.neutral.01",
                    ["phraseID"] = "neutral.01",
                },
                {
                    ["fallback"] = "A real person... not a zombie.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_02.neutral.02",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_02.neutral.02",
                    ["phraseID"] = "neutral.02",
                },
                {
                    ["fallback"] = "He had a name... someone knew him.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_02.neutral.03",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_02.neutral.03",
                    ["phraseID"] = "neutral.03",
                },
                {
                    ["fallback"] = "We're killing each other now... God.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_02.neutral.04",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_02.neutral.04",
                    ["phraseID"] = "neutral.04",
                },
                {
                    ["fallback"] = "He was just trying to survive too...",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_02.neutral.05",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_02.neutral.05",
                    ["phraseID"] = "neutral.05",
                },
                {
                    ["fallback"] = "That was an actual human being lying there.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_02.neutral.06",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_02.neutral.06",
                    ["phraseID"] = "neutral.06",
                },
                {
                    ["fallback"] = "I can't shake this feeling... we took a life.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_02.neutral.07",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_02.neutral.07",
                    ["phraseID"] = "neutral.07",
                },
                {
                    ["fallback"] = "He had boots, a jacket, a life... now he's gone.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_02.neutral.08",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_02.neutral.08",
                    ["phraseID"] = "neutral.08",
                },
                {
                    ["fallback"] = "Killing people... what are we becoming?",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_02.neutral.09",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_02.neutral.09",
                    ["phraseID"] = "neutral.09",
                },
                {
                    ["fallback"] = "That was somebody's family once.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_02.neutral.10",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_02.neutral.10",
                    ["phraseID"] = "neutral.10",
                },
            },
        },
    },
    ["semantic.combat.human_kill.shaken.line_03"] = {
        ["canonicalConcept"] = "SEMANTIC_COMBAT_HUMAN_KILL_SHAKEN_LINE_03",
        ["contentOwner"] = "projecthoomans.dialogue_content.combat_human",
        ["id"] = "phrase.semantic.combat.human_kill.shaken.line_03",
        ["semanticTemplateID"] = "semantic.combat.human_kill.shaken.line_03",
        ["styles"] = {
            ["neutral"] = {
                {
                    ["fallback"] = "He's down... let's just get out of here.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_03.neutral.01",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_03.neutral.01",
                    ["phraseID"] = "neutral.01",
                },
                {
                    ["fallback"] = "Please... can we just leave this place?",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_03.neutral.02",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_03.neutral.02",
                    ["phraseID"] = "neutral.02",
                },
                {
                    ["fallback"] = "Don't search him. Let's just go.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_03.neutral.03",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_03.neutral.03",
                    ["phraseID"] = "neutral.03",
                },
                {
                    ["fallback"] = "I don't want to be here anymore.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_03.neutral.04",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_03.neutral.04",
                    ["phraseID"] = "neutral.04",
                },
                {
                    ["fallback"] = "He's dead. We need to leave before others show up.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_03.neutral.05",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_03.neutral.05",
                    ["phraseID"] = "neutral.05",
                },
                {
                    ["fallback"] = "Let's grab what we need and run.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_03.neutral.06",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_03.neutral.06",
                    ["phraseID"] = "neutral.06",
                },
                {
                    ["fallback"] = "I can't stay near his body. Come on.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_03.neutral.07",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_03.neutral.07",
                    ["phraseID"] = "neutral.07",
                },
                {
                    ["fallback"] = "He's dead... let's just move away.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_03.neutral.08",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_03.neutral.08",
                    ["phraseID"] = "neutral.08",
                },
                {
                    ["fallback"] = "Get me out of here. Please.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_03.neutral.09",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_03.neutral.09",
                    ["phraseID"] = "neutral.09",
                },
                {
                    ["fallback"] = "It's done. Don't look back. Walk.",
                    ["id"] = "phrase.semantic.combat.human_kill.shaken.line_03.neutral.10",
                    ["key"] = "conversation.content.semantic.combat.human_kill.shaken.line_03.neutral.10",
                    ["phraseID"] = "neutral.10",
                },
            },
        },
    },
    ["semantic.combat.human_kill.supportive.line_01"] = {
        ["canonicalConcept"] = "SEMANTIC_COMBAT_HUMAN_KILL_SUPPORTIVE_LINE_01",
        ["contentOwner"] = "projecthoomans.dialogue_content.combat_human",
        ["id"] = "phrase.semantic.combat.human_kill.supportive.line_01",
        ["semanticTemplateID"] = "semantic.combat.human_kill.supportive.line_01",
        ["styles"] = {
            ["neutral"] = {
                {
                    ["fallback"] = "He's down. You alright?",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_01.neutral.01",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_01.neutral.01",
                    ["phraseID"] = "neutral.01",
                },
                {
                    ["fallback"] = "Got the shooter. Did you take any hits?",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_01.neutral.02",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_01.neutral.02",
                    ["phraseID"] = "neutral.02",
                },
                {
                    ["fallback"] = "He's dead. Are you hurt anywhere?",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_01.neutral.03",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_01.neutral.03",
                    ["phraseID"] = "neutral.03",
                },
                {
                    ["fallback"] = "Took him down. Check yourself over.",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_01.neutral.04",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_01.neutral.04",
                    ["phraseID"] = "neutral.04",
                },
                {
                    ["fallback"] = "Threat is eliminated. You safe?",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_01.neutral.05",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_01.neutral.05",
                    ["phraseID"] = "neutral.05",
                },
                {
                    ["fallback"] = "I got him off you. Breathe.",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_01.neutral.06",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_01.neutral.06",
                    ["phraseID"] = "neutral.06",
                },
                {
                    ["fallback"] = "He's not getting back up. You good?",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_01.neutral.07",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_01.neutral.07",
                    ["phraseID"] = "neutral.07",
                },
                {
                    ["fallback"] = "Downed the gunman. Stay with me.",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_01.neutral.08",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_01.neutral.08",
                    ["phraseID"] = "neutral.08",
                },
                {
                    ["fallback"] = "It's okay, I got him. Check your wounds.",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_01.neutral.09",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_01.neutral.09",
                    ["phraseID"] = "neutral.09",
                },
                {
                    ["fallback"] = "Shooter's dead. We're still standing.",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_01.neutral.10",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_01.neutral.10",
                    ["phraseID"] = "neutral.10",
                },
            },
        },
    },
    ["semantic.combat.human_kill.supportive.line_02"] = {
        ["canonicalConcept"] = "SEMANTIC_COMBAT_HUMAN_KILL_SUPPORTIVE_LINE_02",
        ["contentOwner"] = "projecthoomans.dialogue_content.combat_human",
        ["id"] = "phrase.semantic.combat.human_kill.supportive.line_02",
        ["semanticTemplateID"] = "semantic.combat.human_kill.supportive.line_02",
        ["styles"] = {
            ["neutral"] = {
                {
                    ["fallback"] = "It's over. Stay close to me.",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_02.neutral.01",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_02.neutral.01",
                    ["phraseID"] = "neutral.01",
                },
                {
                    ["fallback"] = "He's dead. Keep tight on my shoulder.",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_02.neutral.02",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_02.neutral.02",
                    ["phraseID"] = "neutral.02",
                },
                {
                    ["fallback"] = "Fight's ending. Don't wander off.",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_02.neutral.03",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_02.neutral.03",
                    ["phraseID"] = "neutral.03",
                },
                {
                    ["fallback"] = "He won't hurt us now. Stay near.",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_02.neutral.04",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_02.neutral.04",
                    ["phraseID"] = "neutral.04",
                },
                {
                    ["fallback"] = "Target down. Stick close while we clear.",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_02.neutral.05",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_02.neutral.05",
                    ["phraseID"] = "neutral.05",
                },
                {
                    ["fallback"] = "Got him. Stay behind cover with me.",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_02.neutral.06",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_02.neutral.06",
                    ["phraseID"] = "neutral.06",
                },
                {
                    ["fallback"] = "It's handled. We stick together.",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_02.neutral.07",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_02.neutral.07",
                    ["phraseID"] = "neutral.07",
                },
                {
                    ["fallback"] = "Threat dropped. Keep close until it's quiet.",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_02.neutral.08",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_02.neutral.08",
                    ["phraseID"] = "neutral.08",
                },
                {
                    ["fallback"] = "He's finished. I've got your back.",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_02.neutral.09",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_02.neutral.09",
                    ["phraseID"] = "neutral.09",
                },
                {
                    ["fallback"] = "Down. Don't leave my side.",
                    ["id"] = "phrase.semantic.combat.human_kill.supportive.line_02.neutral.10",
                    ["key"] = "conversation.content.semantic.combat.human_kill.supportive.line_02.neutral.10",
                    ["phraseID"] = "neutral.10",
                },
            },
        },
    },
    ["semantic.combat.human_kill.supportive.line_03"] = {
        ["canonicalConcept"] = "SEMANTIC_COMBAT_HUMAN_KILL_SUPPORTIVE_LINE_03",
        ["contentOwner"] = "projecthoomans.dialogue_content.combat_human",
